<?php require_once __DIR__."/db.php";require_once __DIR__."/functions.php";admin_only();$logs=$conn->query("SELECT l.*,a.username FROM event_audit_logs l LEFT JOIN admins a ON a.id=l.admin_id ORDER BY l.id DESC LIMIT 100")->fetch_all(MYSQLI_ASSOC);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audit Log</title><link rel="stylesheet" href="style.css"></head><body><?php include "top.php";?><main class="container"><section class="card"><?php flashes();?><h2>Recent Event Changes</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Action</th><th>Event</th><th>Details</th><th>Admin</th><th>Date</th></tr></thead><tbody><?php if(!$logs):?><tr><td colspan="6" class="empty">No changes recorded yet.</td></tr><?php endif;?><?php foreach($logs as $l):?><tr><td><?=(int)$l["id"]?></td><td><?=e($l["action"])?></td><td>#<?=(int)$l["event_id"]?></td><td><?=e($l["details"])?></td><td><?=e($l["username"]??"admin")?></td><td><?=e($l["created_at"])?></td></tr><?php endforeach;?></tbody></table></div></section></main><?php include "bottom.php";?></body></html>